function watchysLotRows(PDO $db,$sql,$args=[]){$s=$db->prepare($sql);$s->execute($args);return $s->fetchAll(PDO::FETCH_ASSOC);}
function watchysLotTable(PDO $db,$p,$name,$ddl)
{
 $r=watchysLotRows($db,'SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[$p.$name]);if(!$r){return false;}if(count($r)!==1||strtoupper($r[0]['ENGINE'])!=='INNODB'){throw new RuntimeException('Moteur de table inattendu : '.$name);}
