 $columns=watchysLotRows($db,'SHOW COLUMNS FROM `'.$p.$name.'`');if(array_column($columns,'Field')!==array_keys($expected)){throw new RuntimeException('Colonnes non reconnues : '.$name);}
 foreach($columns as $c){$e=$expected[$c['Field']];$type=preg_replace('/\b(int|bigint)\([0-9]+\)/','$1',strtolower($c['Type']));if($type!==$e['type']||$c['Null']!==$e['null']||str_contains($c['Extra'],'auto_increment')!==$e['auto']){throw new RuntimeException('Type non reconnu : '.$name.'.'.$c['Field']);}}
 $unique=[];foreach(watchysLotRows($db,'SHOW INDEX FROM `'.$p.$name.'`') as $idx){if((int)$idx['Non_unique']===0){$unique[$idx['Key_name']][(int)$idx['Seq_in_index']]=$idx['Column_name'];}}foreach($unique as &$u){ksort($u);$u=implode(',',array_values($u));}unset($u);
 $wanted=['watchys_stock_component'=>['id_product,id_product_attribute,id_shop'],'watchys_stock_permit'=>['connection_id,id_stock_available'],'watchys_native_operation'=>['operation_key','request_key'],'watchys_native_effect'=>['id_effect','operation_key,sequence_no'],'watchys_received_return'=>['id_receipt','request_key']][$name];$actual=array_values($unique);sort($actual);sort($wanted);if($actual!==$wanted){throw new RuntimeException('Clés non reconnues : '.$name);}
