 $hooks=$rows('SELECT h.name,m.name AS module_name FROM `'.$p.'hook` h JOIN `'.$p.'hook_module` hm ON hm.id_hook=h.id_hook JOIN `'.$p.'module` m ON m.id_module=hm.id_module WHERE hm.id_shop=1 AND m.active=1 AND LOWER(h.name) LIKE \'action%before\' ORDER BY h.name,m.name');
