 foreach(WatchysNativeSchema::definitions($p) as $name=>$ddl){$count=watchysLotTable($db,$p,$name,$ddl);if($count!==false&&$count!==0){if($name!=='watchys_stock_component'){throw new RuntimeException('Table native déjà alimentée : '.$name);}foreach($rows('SELECT * FROM `'.$p.$name.'`') as $r){if((int)$r['enabled']!==0||(int)$r['id_shop']!==1||(int)$r['id_product_attribute']!==0||!in_array((int)$r['id_product'],$manifest['componentIds'],true)){throw new RuntimeException('Registre de stock déjà activé ou étranger.');}}}}
